-- Daily challenges for 2026-11-21: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-21. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('enjoying-rainy-days', 'Enjoying Rainy Days', 'For anyone whose mood sinks with the clouds. Each day is one small way to find comfort, coziness or a little joy in rain, drizzle and gray skies, indoors or out, instead of just waiting for the sun.', 'Wellbeing', 365, array['Mindfulness', 'Self-Care']::text[], 1, '2026-11-21T17:00:00+00:00'::timestamptz),
  ('getting-to-know-your-local-history', 'Getting to Know Your Local History', 'For anyone who wants to feel more rooted where they live. Each day is one small way to learn the stories of your street, town or city, from old buildings and street names to the people who came before.', 'Connection', 365, array['Values', 'Loneliness']::text[], 1, '2026-11-21T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('enjoying-rainy-days', 'getting-to-know-your-local-history');

